import contentstack from 'contentstack';
import { ContentstackClientConfig, ContentstackParams } from '../types';

const getStack = (config: ContentstackClientConfig) => {
  const options: Record<string, any> = {
    api_key: config.apiKey,
    delivery_token: config.deliveryToken,
    environment: config.environment,
  };

  if (config.livePreview) {
    options.live_preview = {
      management_token: config.livePreview.managementToken,
      enable: config.livePreview.enable,
      host: config.livePreview.host,
    };
  }

  return contentstack.Stack(options);
};

export const getEntry = async (
  config: ContentstackClientConfig,
  contentTypeUid: string,
  entryUid: string,
  fields?: string[]
) => {
  const stack = getStack(config);
  const query = stack.ContentType(contentTypeUid).Entry(entryUid);
  if (fields) {
    query.only(fields);
  }
  const result = await query.fetch();
  return result;
};

export const getSingleEntry = async (
  config: ContentstackClientConfig,
  contentTypeUid: string,
  fields?: string[]
) => {
  const stack = getStack(config);
  const query = stack.ContentType(contentTypeUid).Entry();
  if (fields) {
    query.only(fields);
  }
  const result = await query.fetch();
  return result;
};

export const findSingletonEntry = async (
  config: ContentstackClientConfig,
  contentTypeUid: string,
  fields?: string[]
) => {
  const stack = getStack(config);
  const query = stack.ContentType(contentTypeUid).Query();
  if (fields) {
    query.only(fields);
  }
  const result = await query.find();
  return result;
};
