export const parseArgs = (argv: string[]): ContentstackParams => {
  const program = new Command();

  program
    .option('--api-key <key>', 'Contentstack API Key')
    .option('--delivery-token <token>', 'Contentstack Delivery Token')
    .option('--environment <env>', 'Contentstack Environment')
    .option('--live-preview-management-token <token>', 'Live Preview Management Token')
    .option('--live-preview-enable <enable>', 'Enable Live Preview')
    .option('--live-preview-host <host>', 'Live Preview Host')
    .parse(argv);

